    #[test]
    fn copy_strips_frame_and_trailing_whitespace_from_transcript() {
        let mut app = clean_app();
        // A transcript row whose visible form carries trailing spaces and a
        // trailing blank line; stored lines never hold the box frame (`│`) because
        // it is drawn solely by the terminal widget, so copy must not add it.
        app.push_event(Event::Text("hello world".to_owned()));
        app.push_event(Event::Text("second line".to_owned()));
        app.flush_pending_text();
        app.copy_to_clipboard();
        let escape = app
            .take_pending_osc_52()
            .expect("a clipboard escape is staged");
        // The escape is OSC 52: `\x1b]52;c;<base64>\x07`, with no raw frame char
        // and no trailing newline in the decoded content.
        assert!(escape.starts_with("\u{1b}]52;c;"));
        assert!(escape.ends_with('\u{7}'));
        assert!(!escape.contains('│'));
        assert!(!escape.ends_with('\n'));
        let decoded = base64_decode(&escape["]52;c;".len()..escape.len() - 1]);
        assert_eq!(decoded, "hello world\nsecond line");
        // A second copy with nothing new staged must not resend a stale escape.
        app.copy_to_clipboard();
        assert!(app.take_pending_osc_52().is_none());
    }

